svg.script:
//!export-start
let _pn_value = 0;
let _pn_decimals = 1;
let _ps_unit = '';
let _pb_disabled = false;
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.unit = String(_ps_unit);
    el.disabled = toBool(_pb_disabled);
    el.value = toNum(_pn_value).toFixed(Math.max(0, Math.round(toNum(_pn_decimals))));
}

function putValue(id, value) {
    if (Date.now() < __busyUntil && ["_pn_value"].indexOf(id) >= 0) return;
    if (id === '_pn_value') { _pn_value = toNum(value); }
    if (id === '_pn_decimals') { _pn_decimals = toNum(value); }
    if (id === '_ps_unit') { _ps_unit = String(value); }
    if (id === '_pb_disabled') { _pb_disabled = toBool(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

(function () {
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.rejectUpdatesOnFocus = true;
})();

function fitBox() {
    var root = document.getElementById('ob_root');
    var fo = document.getElementById('ob_fo');
    var el = document.getElementById('ob_el');
    if (!root || !fo || !el) return;
    var w = parseFloat(root.getAttribute('width')) || 192;
    var h = parseFloat(root.getAttribute('height')) || 48;
    if (root.getAttribute('viewBox') !== '0 0 ' + w + ' ' + h) {
        root.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    fo.setAttribute('width', w);
    fo.setAttribute('height', h);

}

(function () {
    var root = document.getElementById('ob_root');
    fitBox();
    if (root && window.MutationObserver) {
        new MutationObserver(fitBox).observe(root, { attributes: true, attributeFilter: ['width', 'height'] });
    }
})();

var __pending = null;
function commitInput() {
    if (__pending === null) return;
    var v = parseFloat(String(__pending).replace(',', '.'));
    __pending = null;
    __busyUntil = Date.now() + 1000;
    if (isNaN(v)) { apply(); return; }
    _pn_value = v;
    postValue('_pn_value', v);
}

(function () {
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.addEventListener('input', function (ev) {
        var src = ev.composedPath ? ev.composedPath()[0] : ev.target;
        __pending = (src && src.value !== undefined) ? src.value : el.value;
        __busyUntil = Date.now() + 60000;
    });
    el.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter') { commitInput(); }
        if (ev.key === 'Escape') { __pending = null; __busyUntil = 0; apply(); }
    });
    el.addEventListener('focusout', commitInput);
})();

apply();
